<script setup lang="ts">
import { reactive,ref } from 'vue';import { ElMessage } from 'element-plus';
import { api } from '../api/client';import { user } from '../session';import AccountSecurity from './AccountSecurity.vue';
const password=reactive({current:'',next:'',confirm:''}),busy=ref(false);
async function save(){if(busy.value)return;if(password.next.length<15)return ElMessage.warning('新密码至少 15 位');if(password.next!==password.confirm)return ElMessage.warning('两次新密码不一致');busy.value=true;try{await api.changePassword(password.current,password.next);ElMessage.success('密码已更新，其他设备的登录会话已撤销')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false;password.current='';password.next='';password.confirm=''}}
</script>
<template><div class="primary-page profile-page"><div class="primary-page-heading"><div><h1>账号安全</h1><p>保护统一身份，安全设置适用于所有接入应用。</p></div></div><div class="primary-page-scroll profile-scroll" tabindex="0" aria-label="账号安全内容"><div class="profile-body"><section class="panel profile-summary account-panel"><el-avatar :size="56">{{user?.name.slice(0,1)}}</el-avatar><div><h2>{{user?.name}}</h2><p>{{user?.username||'尚未设置账号'}} · {{user?.departmentName||'未设置部门'}}</p></div><el-tag effect="plain">{{user?.roles?.some(role=>role.key==='platform-admin')?'平台管理员':'成员'}}</el-tag></section><section class="panel security-panel"><div class="section-title"><h2>登录密码</h2><span>修改后保留当前会话</span></div><el-form label-position="top" class="password-form" @submit.prevent="save"><el-form-item label="当前密码"><el-input v-model="password.current" type="password" show-password autocomplete="current-password" maxlength="128" :disabled="busy"/></el-form-item><div class="form-grid"><el-form-item label="新密码"><el-input v-model="password.next" type="password" show-password autocomplete="new-password" placeholder="至少 15 位字符" maxlength="128" :disabled="busy"/></el-form-item><el-form-item label="确认新密码"><el-input v-model="password.confirm" type="password" show-password autocomplete="new-password" maxlength="128" :disabled="busy"/></el-form-item></div><el-button type="primary" native-type="submit" :loading="busy" :disabled="!password.current||!password.next">更新密码</el-button></el-form></section><AccountSecurity class="protection-panel"/></div></div></div></template>
